SELECT s.country, CASE WHEN s.rating >= 4.0 THEN 'high' WHEN s.rating >= 2.2 THEN 'mid' ELSE 'low' END AS rating_bucket, COUNT(*) AS num_store_sales, MAX(ss.units) - MIN(ss.units) AS units_range FROM store_sales ss LEFT JOIN products p ON ss.product_id = p.id RIGHT JOIN suppliers s ON p.supplier_id = s.id WHERE p.launch_date BETWEEN '2024-07-01' AND '2025-03-29' GROUP BY s.country, CASE WHEN s.rating >= 4.0 THEN 'high' WHEN s.rating >= 2.2 THEN 'mid' ELSE 'low' END HAVING COUNT(*) > 1
